        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('11011111-0000-4000-8000-000000000001', 'Dimensional formula of Planck''s constant h (E = hν) is identical to that of:', '{"A":"Linear momentum","B":"Angular momentum","C":"Torque","D":"Force"}'::jsonb, 'B', 'MCQ', 'Physics', 'Units and Measurements', 1, '[ML²T⁻²]/[T⁻¹] = [ML²T⁻¹], same as angular momentum L = mvr.', NULL, NULL, '[ML²T⁻²]/[T⁻¹] = [ML²T⁻¹], same as angular momentum L = mvr.', 'EASY', true),
        ('11011111-0000-4000-8000-000000000002', 'Number of significant figures in 0.004050 m is:', '{"A":"3","B":"4","C":"5","D":"6"}'::jsonb, 'B', 'MCQ', 'Physics', 'Units and Measurements', 1, 'Leading zeroes are insignificant; trailing zero after decimal counts -> 4,0,5,0 = 4.', NULL, NULL, 'Leading zeroes are insignificant; trailing zero after decimal counts -> 4,0,5,0 = 4.', 'EASY', true),
        ('11011111-0000-4000-8000-000000000003', 'Which physical quantity is dimensionless yet possesses an SI unit?', '{"A":"Relative density","B":"Plane angle (radian)","C":"Strain","D":"Refractive index"}'::jsonb, 'B', 'MCQ', 'Physics', 'Units and Measurements', 1, 'Plane angle = arc/radius is dimensionless, SI unit radian.', NULL, NULL, 'Plane angle = arc/radius is dimensionless, SI unit radian.', 'EASY', true),
        ('11011111-0000-4000-8000-000000000004', '1 parsec is approximately equal to:', '{"A":"3.26 light years","B":"9.46 × 10¹⁵ m","C":"1.496 × 10¹¹ m","D":"10¹² m"}'::jsonb, 'A', 'MCQ', 'Physics', 'Units and Measurements', 1, '1 parsec ≈ 3.08 × 10¹⁶ m ≈ 3.26 light years.', NULL, NULL, '1 parsec ≈ 3.08 × 10¹⁶ m ≈ 3.26 light years.', 'EASY', true),
        ('11011111-0000-4000-8000-000000000005', 'In the equation P = (a - t²)/(bx), if P is pressure, x is distance and t is time, dimensions of a/b are:', '{"A":"[ML⁰T⁻²]","B":"[MT⁻²]","C":"[L²T⁻¹]","D":"[ML⁻¹T⁻²]"}'::jsonb, 'B', 'MCQ', 'Physics', 'Units and Measurements', 1, '[a]=[T²]; [b]=[T²]/([ML⁻¹T⁻²][L])=[M⁻¹T⁴] => [a/b]=[MT⁻²].', NULL, NULL, '[a]=[T²]; [b]=[T²]/([ML⁻¹T⁻²][L])=[M⁻¹T⁴] => [a/b]=[MT⁻²].', 'EASY', true),
        ('11011111-0000-4000-8000-000000000006', 'Assertion (A): Dimensional consistency is a necessary but not sufficient condition for physical correctness of an equation.
        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('11011111-0000-4000-8000-0000000000c9', '(a) State Bernoulli''s principle and derive the equation P + ½ρv² + ρgh = constant for a steady, incompressible, non-viscous flow.
(b) Mention two practical applications.
(c) Water flows out of a small hole at the bottom of a wide tank filled to height 5 m. Find the speed of efflux (g = 10 m/s²).', NULL, NULL, 'LA', 'Physics', 'Fluids', 5, '(a) For streamline flow of an ideal fluid, sum of pressure energy, kinetic energy per unit volume, and gravitational potential energy per unit volume remains constant.
